package in.recallradar;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Service class TokenService { final AppProperties p; TokenService(AppProperties p){this.p=p;} String access(AppUser u){var now=Instant.now();return Jwts.builder().subject(u.id.toString()).claim("email",u.email).claim("role",u.role).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(p.accessMinutes()*60))).signWith(Keys.hmacShaKeyFor(p.jwtSecret().getBytes(StandardCharsets.UTF_8))).compact();} String subject(String x){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(p.jwtSecret().getBytes(StandardCharsets.UTF_8))).build().parseSignedClaims(x).getPayload().getSubject();} String opaque(){return UUID.randomUUID()+"."+UUID.randomUUID();} String hash(String s){try{var d=java.security.MessageDigest.getInstance("SHA-256");return java.util.HexFormat.of().formatHex(d.digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
